/**
 * ChatBox Component
 * Renders the chat message interface
 */

export interface ChatBoxProps {
  title: string;
  placeholder: string;
  onSend: (message: string) => void;
}

export class ChatBox {
  private container: HTMLElement | null = null;
  private props: ChatBoxProps;

  constructor(props: ChatBoxProps) {
    this.props = props;
  }

  render(container: HTMLElement): void {
    this.container = container;
    this.container.innerHTML = `
      <div class="chatbox">
        <div class="chatbox-header">
          <h3>${this.props.title}</h3>
        </div>
        <div class="chatbox-messages"></div>
        <div class="chatbox-input">
          <input 
            type="text" 
            class="chatbox-input-field" 
            placeholder="${this.props.placeholder}"
            aria-label="Chat message input"
          />
          <button class="chatbox-send-btn" aria-label="Send message">Send</button>
        </div>
      </div>
    `;

    this.attachEventListeners();
  }

  private attachEventListeners(): void {
    const input = this.container?.querySelector('.chatbox-input-field') as HTMLInputElement;
    const button = this.container?.querySelector('.chatbox-send-btn') as HTMLButtonElement;

    const sendMessage = () => {
      if (input.value.trim()) {
        this.props.onSend(input.value);
        input.value = '';
        input.focus();
      }
    };

    button?.addEventListener('click', sendMessage);
    input?.addEventListener('keypress', (e) => {
      if (e.key === 'Enter') {
        sendMessage();
      }
    });
  }
}
