'use client';

import { useState, useCallback, useRef } from 'react';
import type { StreamingParams } from './types';

interface UseStreamingSummaryOptions {
  onChunk?: (chunk: string) => void;
  onComplete?: (fullText: string) => void;
  onError?: (error: string) => void;
}

export interface UseStreamingSummaryReturn {
  streamedText: string;
  isStreaming: boolean;
  error: string | null;
  startStreaming: (params: StreamingParams) => Promise<void>;
  abortStreaming: () => void;
  reset: () => void;
}

export function useStreamingSummary(
  options?: UseStreamingSummaryOptions
): UseStreamingSummaryReturn {
  const [streamedText, setStreamedText] = useState('');
  const [isStreaming, setIsStreaming] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const abortControllerRef = useRef<AbortController | null>(null);
  const accumulatedRef = useRef('');
  const rafIdRef = useRef<number | null>(null);

  const reset = useCallback(() => {
    setStreamedText('');
    setError(null);
    setIsStreaming(false);
    accumulatedRef.current = '';
    if (rafIdRef.current !== null) {
      cancelAnimationFrame(rafIdRef.current);
      rafIdRef.current = null;
    }
  }, []);

  const abortStreaming = useCallback(() => {
    abortControllerRef.current?.abort();
    abortControllerRef.current = null;
    if (rafIdRef.current !== null) {
      cancelAnimationFrame(rafIdRef.current);
      rafIdRef.current = null;
    }
    setIsStreaming(false);
  }, []);

  // Batch rapid chunk updates into a single rAF to avoid thrashing React
  const scheduleUpdate = useCallback(() => {
    if (rafIdRef.current !== null) return;
    rafIdRef.current = requestAnimationFrame(() => {
      rafIdRef.current = null;
      setStreamedText(accumulatedRef.current);
    });
  }, []);

  const startStreaming = useCallback(
    async (params: StreamingParams) => {
      const {
        documentIds,
        token,
        customPrompt,
        yaviLlmConfigName,
        separate,
        fileNameMap,
        streamUrl,
      } = params;

      accumulatedRef.current = '';
      setStreamedText('');
      setError(null);
      setIsStreaming(true);

      const controller = new AbortController();
      abortControllerRef.current = controller;

      try {
        const res = await fetch(streamUrl, {
          method: 'POST',
          headers: {
            'Content-Type': 'application/json',
            Authorization: `Bearer ${token}`,
          },
          body: JSON.stringify({
            documentIds,
            customPrompt,
            yaviLlmConfigName,
            separate,
          }),
          signal: controller.signal,
        });

        if (!res.ok) {
          const errData = await res.json().catch(() => null);
          const msg = errData?.error ?? `Request failed (${res.status})`;
          setError(msg);
          setIsStreaming(false);
          options?.onError?.(msg);
          return;
        }

        const reader = res.body?.getReader();
        if (!reader) {
          const msg = 'No response body from stream endpoint';
          setError(msg);
          setIsStreaming(false);
          options?.onError?.(msg);
          return;
        }

        const decoder = new TextDecoder();
        let buffer = '';

        if (separate) {
          // ── SEPARATE MODE: one section per document ──────────────────────
          const documentOrder: string[] = [];
          const documentContent: Record<string, string> = {};

          const rebuildOutput = () => {
            let output = '';
            for (let i = 0; i < documentOrder.length; i++) {
              const docId = documentOrder[i];
              const name = fileNameMap?.[docId] ?? `Document ${i + 1}`;
              if (i > 0) output += '\n\n---\n\n';
              output += `### 📄 ${name}\n\n`;
              output += documentContent[docId] ?? '';
            }
            accumulatedRef.current = output;
            scheduleUpdate();
            options?.onChunk?.(output);
          };

          while (true) {
            const { done, value } = await reader.read();
            if (done) break;

            buffer += decoder.decode(value, { stream: true });
            const lines = buffer.split('\n');
            buffer = lines.pop() ?? '';

            for (const line of lines) {
              const trimmed = line.trim();
              if (!trimmed || !trimmed.startsWith('data: ')) continue;
              const data = trimmed.slice(6).trim();
              if (!data || data === '[DONE]') continue;

              try {
                const parsed = JSON.parse(data);

                if (parsed.type === 'document_start') {
                  const id = parsed.document_id as string;
                  if (!documentOrder.includes(id)) {
                    documentOrder.push(id);
                    documentContent[id] = '';
                  }
                  rebuildOutput();
                } else if (parsed.type === 'document_chunk') {
                  const id = parsed.document_id as string;
                  if (!documentOrder.includes(id)) {
                    documentOrder.push(id);
                    documentContent[id] = '';
                  }
                  if (parsed.content) {
                    documentContent[id] += parsed.content as string;
                    rebuildOutput();
                  }
                } else if (parsed.type === 'document_complete') {
                  const id = parsed.document_id as string;
                  if (parsed.final_summary) {
                    documentContent[id] = parsed.final_summary as string;
                    rebuildOutput();
                  }
                }

                if (parsed.error) {
                  setError(parsed.error as string);
                  options?.onError?.(parsed.error as string);
                }
              } catch {
                // non-JSON line — skip
              }
            }
          }
        } else {
          // ── COMBINE MODE: single streamed output ─────────────────────────
          while (true) {
            const { done, value } = await reader.read();
            if (done) break;

            buffer += decoder.decode(value, { stream: true });
            const lines = buffer.split('\n');
            buffer = lines.pop() ?? '';

            for (const line of lines) {
              const trimmed = line.trim();
              if (!trimmed || !trimmed.startsWith('data: ')) continue;
              const data = trimmed.slice(6).trim();
              if (!data || data === '[DONE]') continue;

              try {
                const parsed = JSON.parse(data);
                if (typeof parsed.content === 'string') {
                  accumulatedRef.current += parsed.content;
                  scheduleUpdate();
                  options?.onChunk?.(parsed.content);
                }
                if (parsed.error) {
                  setError(parsed.error as string);
                  options?.onError?.(parsed.error as string);
                }
              } catch {
                // non-JSON line — skip
              }
            }
          }
        }

        // Final flush
        if (rafIdRef.current !== null) {
          cancelAnimationFrame(rafIdRef.current);
          rafIdRef.current = null;
        }
        setStreamedText(accumulatedRef.current);
        options?.onComplete?.(accumulatedRef.current);
      } catch (err: any) {
        if (err?.name === 'AbortError') {
          return; // user aborted — not an error
        }
        const msg = err?.message ?? 'Streaming failed';
        console.error('[SummaryWidget] streaming error:', msg);
        setError(msg);
        options?.onError?.(msg);
      } finally {
        setIsStreaming(false);
      }
    },
    [scheduleUpdate, options]
  );

  return { streamedText, isStreaming, error, startStreaming, abortStreaming, reset };
}
