'use client';

import { useState, useCallback, useRef } from 'react';
import type { QnaStreamingParams, Reference } from './types';

interface UseStreamingQnaOptions {
  onChunk?: (chunk: string) => void;
  onComplete?: (fullText: string) => void;
  onError?: (error: string) => void;
  onReferences?: (references: Reference[]) => void;
}

export interface UseStreamingQnaReturn {
  streamedText: string;
  isStreaming: boolean;
  error: string | null;
  references: Reference[];
  startStreaming: (params: QnaStreamingParams) => Promise<void>;
  abortStreaming: () => void;
  reset: () => void;
}

export function useStreamingQna(
  options?: UseStreamingQnaOptions
): UseStreamingQnaReturn {
  const [streamedText, setStreamedText] = useState('');
  const [isStreaming, setIsStreaming] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [references, setReferences] = useState<Reference[]>([]);

  const abortControllerRef = useRef<AbortController | null>(null);
  const accumulatedRef = useRef('');
  const rafIdRef = useRef<number | null>(null);
  const referencesRef = useRef<Reference[]>([]);

  const reset = useCallback(() => {
    setStreamedText('');
    setError(null);
    setIsStreaming(false);
    setReferences([]);
    accumulatedRef.current = '';
    referencesRef.current = [];
    if (rafIdRef.current !== null) {
      cancelAnimationFrame(rafIdRef.current);
      rafIdRef.current = null;
    }
  }, []);

  const abortStreaming = useCallback(() => {
    abortControllerRef.current?.abort();
    abortControllerRef.current = null;
    if (rafIdRef.current !== null) {
      cancelAnimationFrame(rafIdRef.current);
      rafIdRef.current = null;
    }
    setIsStreaming(false);
  }, []);

  // Batch rapid chunk updates into a single rAF to avoid thrashing React
  const scheduleUpdate = useCallback(() => {
    if (rafIdRef.current !== null) return;
    rafIdRef.current = requestAnimationFrame(() => {
      rafIdRef.current = null;
      setStreamedText(accumulatedRef.current);
      if (referencesRef.current.length > 0) {
        setReferences([...referencesRef.current]);
        options?.onReferences?.(referencesRef.current);
      }
    });
  }, [options]);

  const startStreaming = useCallback(
    async (params: QnaStreamingParams) => {
      const {
        question,
        documentIds,
        token,
        customPrompt,
        yaviLlmConfigName,
        fileNameMap,
        streamUrl,
        topK,
        temperature,
      } = params;

      accumulatedRef.current = '';
      referencesRef.current = [];
      setStreamedText('');
      setReferences([]);
      setError(null);
      setIsStreaming(true);

      const controller = new AbortController();
      abortControllerRef.current = controller;

      try {
        const res = await fetch(streamUrl, {
          method: 'POST',
          headers: {
            'Content-Type': 'application/json',
            Authorization: `Bearer ${token}`,
          },
          body: JSON.stringify({
            question,
            documentIds,
            customPrompt,
            yaviLlmConfigName,
            topK: topK ?? 10,
            temperature: temperature ?? 0.7,
          }),
          signal: controller.signal,
        });

        if (!res.ok) {
          const errData = await res.json().catch(() => null);
          const msg = errData?.error ?? `Request failed (${res.status})`;
          setError(msg);
          setIsStreaming(false);
          options?.onError?.(msg);
          return;
        }

        const reader = res.body?.getReader();
        if (!reader) {
          const msg = 'No response body from stream endpoint';
          setError(msg);
          setIsStreaming(false);
          options?.onError?.(msg);
          return;
        }

        const decoder = new TextDecoder();
        let buffer = '';

        // Stream QnA response with references
        while (true) {
          const { done, value } = await reader.read();
          if (done) break;

          buffer += decoder.decode(value, { stream: true });
          const lines = buffer.split('\n');
          buffer = lines.pop() ?? '';

          for (const line of lines) {
            const trimmed = line.trim();
            if (!trimmed || !trimmed.startsWith('data: ')) continue;
            const data = trimmed.slice(6).trim();
            if (!data || data === '[DONE]') continue;

            try {
              const parsed = JSON.parse(data);

              // Handle answer chunk
              if (parsed.type === 'answer_chunk' || parsed.content) {
                const content = parsed.content ?? parsed.text ?? '';
                if (content) {
                  accumulatedRef.current += content;
                  scheduleUpdate();
                  options?.onChunk?.(content);
                }
              }

              // Handle references
              if (parsed.type === 'references' && parsed.references) {
                const newRefs = Array.isArray(parsed.references)
                  ? parsed.references
                  : [parsed.references];

                newRefs.forEach((ref: any) => {
                  if (ref && ref.document_id && !referencesRef.current.some((r) => r.document_id === ref.document_id && r.chunk_id === ref.chunk_id)) {
                    referencesRef.current.push({
                      document_id: ref.document_id,
                      filename: fileNameMap?.[ref.document_id] ?? ref.filename ?? 'Unknown',
                      content: ref.content ?? '',
                      similarity_score: ref.similarity_score,
                      page: ref.page,
                      chunk_id: ref.chunk_id,
                      metadata: ref.metadata,
                    });
                  }
                });
                scheduleUpdate();
              }

              // Handle metadata with references (from reference-box format)
              if (parsed.type === 'metadata' && parsed.metadatas) {
                const metadataRefs = Object.values(parsed.metadatas).flat() as any[];
                metadataRefs.forEach((ref: any) => {
                  if (ref?.metadata?.document_id) {
                    const docId = ref.metadata.document_id;
                    if (!referencesRef.current.some((r) => r.document_id === docId)) {
                      referencesRef.current.push({
                        document_id: docId,
                        filename: fileNameMap?.[docId] ?? ref.metadata.filename ?? 'Unknown',
                        content: ref.metadata.content ?? ref.text ?? '',
                        similarity_score: ref.similarity_score,
                        page: ref.metadata.page,
                        metadata: ref.metadata,
                      });
                    }
                  }
                });
                scheduleUpdate();
              }

              if (parsed.error) {
                setError(parsed.error as string);
                options?.onError?.(parsed.error as string);
              }
            } catch {
              // non-JSON line — skip
            }
          }
        }

        setIsStreaming(false);
        options?.onComplete?.(accumulatedRef.current);
      } catch (err: any) {
        if (err.name !== 'AbortError') {
          const msg = err.message ?? 'Streaming error occurred';
          setError(msg);
          options?.onError?.(msg);
        }
        setIsStreaming(false);
      }
    },
    [options, scheduleUpdate]
  );

  return {
    streamedText,
    isStreaming,
    error,
    references,
    startStreaming,
    abortStreaming,
    reset,
  };
}
