import type {
  WidgetDocument,
  NamespaceData,
  NamespaceFile,
  LinkedInPostWidgetConfig,
} from './types';

export async function fetchWidgetConfig(
  apiBaseUrl: string,
  widgetId: string,
  token: string
): Promise<WidgetDocument> {
  const res = await fetch(`${apiBaseUrl}/widget/${widgetId}`, {
    headers: { Authorization: `Bearer ${token}` },
    cache: 'no-store',
  });
  if (!res.ok) throw new Error(`Widget fetch failed: ${res.status}`);
  const data = await res.json();
  return (data.widget ?? data) as WidgetDocument;
}

export async function createRagSession(
  apiBaseUrl: string,
  token: string,
  yaviLlmConfigName = 'gpt-4o-mini'
): Promise<{ session_id?: string; [key: string]: any }> {
  const res = await fetch(`${apiBaseUrl}/proxy/rag/rag/api/v2/session`, {
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
      Authorization: `Bearer ${token}`,
    },
    body: JSON.stringify({
      bot_mode: 'standard_v2',
      yavi_llm_config_name: yaviLlmConfigName,
      yavi_embedding_config_name: 'azure-embedding-small',
      llm_parameters: {
        frequency_penalty: 0,
        presence_penalty: 0,
        temperature: 0.7,
        max_tokens: 2000,
        top_p: 1,
      },
    }),
  });

  if (!res.ok) throw new Error(`Session creation failed: ${res.status}`);
  return res.json();
}

