export function resolveDocumentIds(
  selectedFileIds: string[],
  availableFiles: NamespaceFile[]
): string[] {
  const fallbackAll = availableFiles
    .map((f) => f.document_id ?? f.file_id)
    .filter(Boolean) as string[];

  if (!selectedFileIds.length) return fallbackAll;

  const byFileId = new Map<string, string>();
  availableFiles.forEach((f) => {
    byFileId.set(f.file_id, f.document_id ?? f.file_id);
  });

  return selectedFileIds
    .map((id) => byFileId.get(id) ?? id)
    .filter(Boolean);
}

function buildLinkedInPrompt(config: LinkedInPostWidgetConfig): string {
  const {
    postType = 'standard',
    lengthTarget = 'medium',
    tone = 'professional',
    authorPersona = 'professional',
    audienceTarget = 'general',
    contentFocus = 'insights',
    mandatoryHashtags = [],
    blockedHashtags = [],
    hashtagCount = 3,
    includeEmojis = true,
    includeCallToAction = true,
    customInstructions = '',
  } = config;

  const charLimit =
    lengthTarget === 'short' ? 700 : lengthTarget === 'long' ? 3000 : 1500;
  const wordLimit =
    lengthTarget === 'short' ? 100 : lengthTarget === 'long' ? 450 : 225;

  return `You are a professional LinkedIn content creator. Generate a ${postType} LinkedIn post based on the provided content.\n\n**CRITICAL LENGTH CONSTRAINT (MUST FOLLOW):**\n- HARD MAXIMUM: ${charLimit} characters (including spaces, hashtags, and emojis)\n- Aim for approximately ${wordLimit} words or fewer\n- This is a STRICT limit. The post MUST be under ${charLimit} characters total. Do NOT exceed this under any circumstances.\n\n**SPECIFICATIONS:**\n- Tone: ${tone}\n- Author Persona: ${authorPersona}\n- Target Audience: ${audienceTarget}\n- Content Focus: ${contentFocus}\n\n**INSTRUCTIONS:**\n1. Extract key insights from source content\n2. Start with a strong hook in the first 2 lines\n3. Use line breaks for readability\n4. ${includeEmojis ? 'Include relevant professional emojis sparingly' : 'Do not use emojis'}\n5. Base all claims on actual content\n6. Make it engaging and mobile-optimized\n\n**HASHTAGS:**\n- Include exactly ${hashtagCount} hashtags at the end${mandatoryHashtags.length ? `\n- Must include: ${mandatoryHashtags.join(', ')}` : ''}${blockedHashtags.length ? `\n- Never use: ${blockedHashtags.join(', ')}` : ''}\n${includeCallToAction ? '\n**CTA:** Include a brief call-to-action' : ''}${customInstructions ? `\n\n**CUSTOM INSTRUCTIONS:** ${customInstructions}` : ''}\n\n**OUTPUT:** Generate only ready-to-publish LinkedIn post text.`;
}

function extractPostText(payload: any): string {
  if (!payload) return '';
  if (typeof payload === 'string') return payload;
  if (Array.isArray(payload?.summaries) && payload.summaries.length > 0) {
    const first = payload.summaries[0];
    if (typeof first === 'string') return first;
    if (typeof first?.summary === 'string') return first.summary;
  }
  if (typeof payload?.summary === 'string') return payload.summary;
  if (typeof payload?.postContent === 'string') return payload.postContent;
  if (typeof payload?.answer === 'string') return payload.answer;
  return '';
}

export async function generateLinkedInPostFromDocuments(
  apiBaseUrl: string,
  token: string,
  documentIds: string[],
  config: LinkedInPostWidgetConfig,
  yaviLlmConfigName = 'gpt-4o-mini'
): Promise<string> {
  const prompt = buildLinkedInPrompt(config);
  const res = await fetch(`${apiBaseUrl}/proxy/rag/rag/api/v1/summary`, {
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
      Authorization: `Bearer ${token}`,
    },
    body: JSON.stringify({
      custom_prompt: prompt,
      document_ids: documentIds,
      separate: false,
      yavi_llm_config_name: yaviLlmConfigName,
    }),
  });

  if (!res.ok) {
    const text = await res.text();
    throw new Error(`LinkedIn generation failed (${res.status}): ${text}`);
  }

  const data = await res.json();
  const post = extractPostText(data);
  if (!post.trim()) throw new Error('Generated post is empty');
  return post;
}

export async function generateLinkedInPostFromStructuredData(
  apiBaseUrl: string,
  token: string,
  sessionId: string,
  config: LinkedInPostWidgetConfig
): Promise<string> {
  const prompt = buildLinkedInPrompt(config);
  const res = await fetch(`${apiBaseUrl}/structured-chat`, {
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
      Authorization: `Bearer ${token}`,
    },
    body: JSON.stringify({ sessionId, prompt }),
  });

  if (!res.ok) {
    const text = await res.text();
    throw new Error(`Structured LinkedIn generation failed (${res.status}): ${text}`);
  }

  const data = await res.json();
  const post = extractPostText(data);
  if (!post.trim()) throw new Error('Generated post is empty');
  return post;
}
