import React from 'react';

/**
 * Simple markdown-to-React renderer for common markdown patterns.
 * Converts markdown text to JSX elements for proper formatting.
 */
export function renderMarkdown(content: string): React.ReactNode {
  if (!content) return null;

  const elements: React.ReactNode[] = [];
  const lines = content.split('\n');
  let i = 0;

  while (i < lines.length) {
    const line = lines[i];

    // Headings
    const headingMatch = line.match(/^(#{1,6})\s+(.+)$/);

    if (headingMatch) {
      const level = headingMatch[1].length;
      const text = renderInlineMarkdown(headingMatch[2]);

      const HeadingTag = `h${level}` as keyof JSX.IntrinsicElements;

      elements.push(
        <HeadingTag
          key={`heading-${i}`}
          style={{
            marginTop: '0.8em',
            marginBottom: '0.4em',
            lineHeight: 1.4,
          }}
        >
          {text}
        </HeadingTag>
      );

      i++;
      continue;
    }

    // Code blocks
    if (line.trim().startsWith('```')) {
      const codeLines: string[] = [];

      i++;

      while (
        i < lines.length &&
        !lines[i].trim().startsWith('```')
      ) {
        codeLines.push(lines[i]);
        i++;
      }

      i++;

      elements.push(
        <pre
          key={`code-${i}`}
          style={{
            background: '#f5f5f5',
            padding: '12px',
            borderRadius: '6px',
            overflow: 'auto',
            fontSize: '0.9em',
            margin: '0.8em 0',
          }}
        >
          <code>{codeLines.join('\n')}</code>
        </pre>
      );

      continue;
    }

    // Blockquotes
    if (line.trim().startsWith('>')) {
      const quoteLines: string[] = [];

      while (
        i < lines.length &&
        lines[i].trim().startsWith('>')
      ) {
        quoteLines.push(
          lines[i].replace(/^\s*>\s*/, '')
        );

        i++;
      }

      elements.push(
        <blockquote
          key={`quote-${i}`}
          style={{
            borderLeft: '4px solid #ccc',
            paddingLeft: '12px',
            margin: '0.8em 0',
            color: '#666',
            fontStyle: 'italic',
          }}
        >
          {renderMarkdown(quoteLines.join('\n'))}
        </blockquote>
      );

      continue;
    }

    // Lists
    if (
      line.trim().match(/^[-*+]\s+/) ||
      line.trim().match(/^\d+\.\s+/)
    ) {
      const listItems: string[] = [];

      const isOrdered = !!line
        .trim()
        .match(/^\d+\./);

      while (
        i < lines.length &&
        (
          lines[i].trim().match(/^[-*+]\s+/) ||
          lines[i].trim().match(/^\d+\.\s+/)
        )
      ) {
        listItems.push(
          lines[i]
            .replace(/^[-*+]\s+|\d+\.\s+/, '')
            .trim()
        );

        i++;
      }

      const ListTag = isOrdered ? 'ol' : 'ul';

      elements.push(
        <ListTag
          key={`list-${i}`}
          style={{
            margin: '0.8em 0',
            paddingLeft: '20px',
            lineHeight: 1.7,
          }}
        >
          {listItems.map((item, idx) => (
            <li key={idx}>
              {renderInlineMarkdown(item)}
            </li>
          ))}
        </ListTag>
      );

      continue;
    }

    // Empty line
    if (!line.trim()) {
      i++;
      continue;
    }

    // Paragraphs
    const paragraphLines: string[] = [];

    while (
      i < lines.length &&
      lines[i].trim() &&
      !lines[i].match(/^#{1,6}\s+/) &&
      !lines[i].trim().startsWith('```') &&
      !lines[i].trim().startsWith('>') &&
      !lines[i].trim().match(/^[-*+]\s+/) &&
      !lines[i].trim().match(/^\d+\.\s+/)
    ) {
      paragraphLines.push(lines[i]);
      i++;
    }

    if (paragraphLines.length > 0) {
      elements.push(
        <p
          key={`para-${i}`}
          style={{
            margin: '0.8em 0',
            whiteSpace: 'pre-wrap',
            lineHeight: 1.7,
          }}
        >
          {renderInlineMarkdown(
            paragraphLines.join('\n')
          )}
        </p>
      );
    }
  }

  return <>{elements}</>;
}

/**
 * Render inline markdown formatting.
 */
function renderInlineMarkdown(
  text: string
): React.ReactNode {
  if (!text) return null;

  const elements: React.ReactNode[] = [];

  let remaining = text;

  let key = 0;

  const patterns = [
    {
      regex: /^\[([^\]]+)\]\(([^)]+)\)/,
      render: (match: RegExpMatchArray) => (
        <a
          key={key++}
          href={match[2]}
          target="_blank"
          rel="noopener noreferrer"
          style={{
            color: '#3b82f6',
            textDecoration: 'underline',
          }}
        >
          {match[1]}
        </a>
      ),
    },

    {
      regex: /^\*\*(.*?)\*\*/,
      render: (match: RegExpMatchArray) => (
        <strong
          key={key++}
          style={{ fontWeight: 700 }}
        >
          {match[1]}
        </strong>
      ),
    },

    {
      regex: /^__(.*?)__/,
      render: (match: RegExpMatchArray) => (
        <strong
          key={key++}
          style={{ fontWeight: 700 }}
        >
          {match[1]}
        </strong>
      ),
    },

    {
      regex: /^\*(.*?)\*/,
      render: (match: RegExpMatchArray) => (
        <em
          key={key++}
          style={{ fontStyle: 'italic' }}
        >
          {match[1]}
        </em>
      ),
    },

    {
      regex: /^_(.*?)_/,
      render: (match: RegExpMatchArray) => (
        <em
          key={key++}
          style={{ fontStyle: 'italic' }}
        >
          {match[1]}
        </em>
      ),
    },

    {
      regex: /^~~(.*?)~~/,
      render: (match: RegExpMatchArray) => (
        <del
          key={key++}
          style={{
            textDecoration: 'line-through',
          }}
        >
          {match[1]}
        </del>
      ),
    },

    {
      regex: /^`([^`]+)`/,
      render: (match: RegExpMatchArray) => (
        <code
          key={key++}
          style={{
            background: '#f0f0f0',
            padding: '2px 6px',
            borderRadius: '3px',
            fontFamily: 'monospace',
            fontSize: '0.9em',
          }}
        >
          {match[1]}
        </code>
      ),
    },
  ];

  while (remaining.length > 0) {
    let matched = false;

    for (const pattern of patterns) {
      const match = remaining.match(pattern.regex);

      if (match) {
        elements.push(pattern.render(match));

        remaining = remaining.slice(
          match[0].length
        );

        matched = true;

        break;
      }
    }

    if (!matched) {
      elements.push(remaining[0]);

      remaining = remaining.slice(1);
    }
  }

  return <>{elements}</>;
}