/**
 * summary/api.ts
 *
 * All HTTP calls the SummaryWidget makes against the consumer's proxy backend.
 * No Next.js / server dependencies — pure fetch(), works in any environment.
 */
import { jwtDecode } from 'jwt-decode';
import type {
  WidgetDocument,
  RagSessionResponse,
  StructuredSessionResponse,
  NamespaceData,
} from './types';

// ─── Widget config ─────────────────────────────────────────────────────────
interface UserObject {
  access?: string;
  refresh?: string;
  [key: string]: any;
}

interface KeycloakToken {
  exp: number;
  iat: number;
  auth_time?: number;
  jti: string;
  iss: string;
  sub: string;
  typ: string;
  azp?: string;
  sid?: string;
  'allowed-origins'?: string[];
  realm_access?: {
    roles: string[];
  };
  scope?: string;
  email_verified?: boolean;
  name?: string;
  preferred_username?: string;
  given_name?: string;
  family_name?: string;
  email?: string;
  [key: string]: any;
}

interface CustomJWTToken {
  token_type: string;
  exp: number;
  iat: number;
  jti: string;
  user_id: string;
  email: string;
  username: string;
  user_type?: number;
  iss: string;
  [key: string]: any;
}
export async function fetchWidgetConfig(
  apiBaseUrl: string,
  widgetId: string,
  token: string
): Promise<WidgetDocument> {
  const res = await fetch(`${apiBaseUrl}/widget/${widgetId}`, {
    headers: { Authorization: `Bearer ${token}` },
    cache: 'no-store',
  });
  if (!res.ok) throw new Error(`Widget fetch failed: ${res.status}`);
  const data = await res.json();
  // Support both { widget: {...} } and direct object shapes
  return (data.widget ?? data) as WidgetDocument;
}
function isKeycloakToken(token: any): token is KeycloakToken {
  return 'sub' in token && 'azp' in token;
}

function isCustomJWTToken(token: any): token is CustomJWTToken {
  return 'user_id' in token && 'token_type' in token;
}

// ─── Session creation ──────────────────────────────────────────────────────
export async function getServerUserIdFromAccessToken(accessToken: any): Promise<string | null> {
  try {
 

    const decoded: any = jwtDecode(accessToken);

    // Check if it's a Keycloak token
    if (isKeycloakToken(decoded)) {
      return decoded.sub;
    }

    // Check if it's a custom JWT token
    if (isCustomJWTToken(decoded)) {
      return decoded.user_id;
    }

    return null;
  } catch (error) {
    console.error('Error decoding access token for user ID:', error);
    return null;
  }
}
export async function createRagSession(
  apiBaseUrl: string,
  token: string,
  yaviLlmConfigName?: string
): Promise<RagSessionResponse> {
    console.warn('Creating RAG session with token:', token);
       let userId = await getServerUserIdFromAccessToken(token);
  // Use local proxy endpoint instead of hitting backend directly
  const res = await fetch(`${apiBaseUrl}/proxy/rag/rag/api/v2/session`, {
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
      Authorization: `Bearer ${token}`,
    },
    body: JSON.stringify({
        bot_mode: 'standard_v2',
          yavi_llm_config_name:  "gpt-4o-mini",
          yavi_embedding_config_name:
            "azure-embedding-small",
          llm_parameters: {
            frequency_penalty: 0,
            presence_penalty: 0,
            temperature: 0.7,
            max_tokens: 2000,
            top_p: 1,
          },
             user_id: userId,
    }),
  });
  if (!res.ok) throw new Error(`Session creation failed: ${res.status}`);
  return res.json();
}

export async function createStructuredSession(
  apiBaseUrl: string,
  token: string,
  datasetId: string,
  yaviLlmConfigName?: string
): Promise<StructuredSessionResponse> {
  const res = await fetch(`${apiBaseUrl}/session`, {
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
      Authorization: `Bearer ${token}`,
    },
    body: JSON.stringify({
      type: 'structured',
      datasetId,
      yaviLlmConfigName,
    }),
  });
  if (!res.ok) throw new Error(`Structured session failed: ${res.status}`);
  return res.json();
}

// ─── Namespaces / files ────────────────────────────────────────────────────

export async function fetchNamespaces(
  apiBaseUrl: string,
  workspaceId: string,
  token: string
): Promise<NamespaceData[]> {
  const res = await fetch(`${apiBaseUrl}/namespaces/${workspaceId}`, {
    headers: { Authorization: `Bearer ${token}` },
    cache: 'no-store',
  });
  if (!res.ok) throw new Error(`Namespaces fetch failed: ${res.status}`);
  return res.json();
}

// ─── Structured chat (non-streaming) ─────────────────────────────────────

export async function queryStructuredSummary(
  apiBaseUrl: string,
  token: string,
  sessionId: string,
  prompt: string
): Promise<string> {
  // Default prompt if empty (same as source app)
  const finalPrompt = prompt?.trim() || 'summary:';
  
  const res = await fetch(`${apiBaseUrl}/structured-chat`, {
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
      Authorization: `Bearer ${token}`,
    },
    body: JSON.stringify({ sessionId, prompt: finalPrompt }),
  });
  if (!res.ok) throw new Error(`Structured chat failed: ${res.status}`);
  const data = await res.json();
  return data.answer ?? data.explanation ?? '';
}

// ─── Helper: Resolve file_id to document_id mapping ───────────────────────

interface NamespaceFile {
  file_id: string;
  document_id?: string;
  [key: string]: any;
}

/**
 * Build a mapping from file_id → document_id using available files.
 * Falls back to file_id if document_id is not present.
 */
export function buildFileIdToDocumentIdMap(
  availableFiles: NamespaceFile[]
): Record<string, string> {
  const map: Record<string, string> = {};
  availableFiles.forEach((f) => {
    // Use document_id if available, otherwise use file_id
    map[f.file_id] = f.document_id ?? f.file_id;
  });
  return map;
}

/**
 * Resolve selected file_ids to actual document_ids using available files.
 * If no files selected, return all document_ids from available files.
 */
export function resolveDocumentIds(
  selectedFileIds: string[],
  availableFiles: NamespaceFile[]
): string[] {
  const fileIdToDocId = buildFileIdToDocumentIdMap(availableFiles);

  if (selectedFileIds.length > 0) {
    // Use pre-selected file IDs and map them to document IDs
    return selectedFileIds
      .map((fileId) => fileIdToDocId[fileId])
      .filter(Boolean);
  }

  // Fall back: use all document IDs from available files
  return availableFiles
    .map((f) => f.document_id ?? f.file_id)
    .filter(Boolean);
}

/**
 * Build file name map for separate mode display.
 * Maps document_id → display name for summary output.
 */
export function buildFileNameMap(
  availableFiles: NamespaceFile[]
): Record<string, string> {
  const map: Record<string, string> = {};
  availableFiles.forEach((f, index) => {
    const displayName = f.originalName ?? f.fileName ?? `Document ${index + 1}`;
    const docId = f.document_id ?? f.file_id;
    map[docId] = displayName;
  });
  return map;
}
