'use client';

import { useEffect, useState, useCallback } from 'react';
import { fetchWidgetConfig, createRagSession, createStructuredSession, fetchNamespaces, queryQnA, queryStructuredQnA } from './api';
import type { QnaWidgetProps, QnaWidgetConfig, Reference, FileAnswer, QnaAnswer } from './types';
import { FileSelectorDropdown } from '../shared/FileSelectorDropdown';
import './qna.css';

// Reference Accordion Item
const ReferenceItem = ({ reference, index, isExpanded, onToggle }: any) => {
  return (
    <div className="yw-qna-reference-item">
      <button onClick={onToggle} className="yw-qna-reference-header">
        <div className="yw-qna-reference-info">
          <span className="yw-qna-reference-index">Reference {index + 1}</span>
          <span className="yw-qna-reference-source">• {reference.source}</span>
          {reference.similarity_score && <span className="yw-qna-reference-score">• {(reference.similarity_score * 100).toFixed(0)}% match</span>}
        </div>
        <span className={`yw-qna-chevron ${isExpanded ? 'yw-qna-chevron--open' : ''}`}>▼</span>
      </button>
      {isExpanded && <div className="yw-qna-reference-content">{reference.content}</div>}
    </div>
  );
};

export default function QnaWidget({
  widgetId,
  token,
  apiBaseUrl,
  onTokenExpired,
  onError,
  className,
  position = 'inline',
  launcherLabel = 'Q',
  floatingWidth,
  floatingHeight,
}: QnaWidgetProps) {
  const [widget, setWidget] = useState<QnaWidgetConfig | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [availableFiles, setAvailableFiles] = useState<any[]>([]);
  const [isLoadingFiles, setIsLoadingFiles] = useState(true);
  const [selectedFileIds, setSelectedFileIds] = useState<string[]>([]);
  const [sessionId, setSessionId] = useState<string | null>(null);
  const [questions, setQuestions] = useState<string[]>([]);
  const [answers, setAnswers] = useState<Record<string, QnaAnswer>>({});
  const [isProcessing, setIsProcessing] = useState(false);
  const [currentlyProcessing, setCurrentlyProcessing] = useState<string | null>(null);
  const [selectedModel, setSelectedModel] = useState('gpt-4o-mini');
  const [expandedRefs, setExpandedRefs] = useState<Record<string, boolean>>({});
  const [isOpen, setIsOpen] = useState(position !== 'bottom-right');
  const [dataSourceType, setDataSourceType] = useState<'UnStructured' | 'Structured' | null>(null);
  const [resolvedNamespace, setResolvedNamespace] = useState<string | null>(null);

  useEffect(() => {
    setIsOpen(position !== 'bottom-right');
  }, [position]);

  // Initialize widget
  useEffect(() => {
    let isMounted = true;

    const init = async () => {
      try {
        setLoading(true);
        const doc = await fetchWidgetConfig(apiBaseUrl, widgetId, token);
        if (!isMounted) return;
        // The API returns a WidgetDocument; actual config is in doc.config
        const innerConfig: any = (doc as any).config ?? doc;
        setWidget(innerConfig);

        // Set questions: try questions[] first, then checkboxes[]
        const rawQuestions: string[] =
          (Array.isArray(innerConfig.questions) && innerConfig.questions.length > 0)
            ? innerConfig.questions
            : Array.isArray(innerConfig.checkboxes)
            ? innerConfig.checkboxes.map((cb: any) => cb.label || cb)
            : [];
        if (rawQuestions.length > 0) setQuestions(rawQuestions);

        // Set initial model from config
        const models = innerConfig.allowModels;
        if (models && (Array.isArray(models) ? models.length > 0 : models)) {
          const first = Array.isArray(models) ? models[0] : String(models).split(',')[0];
          if (first) setSelectedModel(first.trim());
        }

        setSelectedFileIds(innerConfig.selectedFileIds ?? []);

        // Load files from configured namespace (same pattern as SummaryWidget)
        // with compatibility fallbacks for older widget config shapes.
        const dataSource = innerConfig.dataSources?.[0] ?? (doc as any)?.dataSources?.[0];
        const selectedSource = dataSource?.selectedSource ?? 'UnStructured';
        setDataSourceType(selectedSource as 'UnStructured' | 'Structured');

        const namespace =
          dataSource?.configdetails?.namespace ??
          dataSource?.namespace ??
          innerConfig?.namespace ??
          (doc as any)?.namespace;
        const workspaceId =
          innerConfig.workspaceId ??
          (doc as any).workspaceId;

        // Handle unstructured data: fetch namespaces and files
        if (selectedSource === 'UnStructured' && workspaceId) {
          try {
            console.warn('[QnaWidget] Fetching namespaces with workspaceId:', workspaceId, 'and token:', token, 'and apiBaseUrl:', apiBaseUrl);
            const namespaces = await fetchNamespaces(apiBaseUrl, workspaceId, token);
            if (!isMounted) return;
            let resolvedFiles: any[] = []; 
            let effectiveNamespace: string | null = namespace ?? null;

            if (namespace) {
              const matchedNamespace = namespaces.find((ns: any) => ns.namespace === namespace);
             console.warn('[QnaWidget] Resolved namespaces:', namespaces, 'Matched namespace:', matchedNamespace);
              if (matchedNamespace) {
                resolvedFiles = matchedNamespace.source;
                effectiveNamespace = matchedNamespace.namespace ?? namespace;
              }
            }

            // Fallback: if namespace is missing or doesn't match, use all files across namespaces.
            if (resolvedFiles.length === 0) {
              resolvedFiles = namespaces.flatMap((ns: any) => ns.source ?? ns.files ?? []);
              effectiveNamespace = effectiveNamespace ?? namespaces[0]?.namespace ?? null;
            }

            setAvailableFiles(resolvedFiles);
            setResolvedNamespace(effectiveNamespace);
          } catch (nsErr) {
            console.warn('[QnaWidget] namespace fetch failed (non-fatal):', nsErr);
          } finally {
            if (isMounted) setIsLoadingFiles(false);
          }
        } else if (isMounted) {
          setResolvedNamespace(namespace ?? null);
          setIsLoadingFiles(false);
        }

        // Create session based on data source type
        let session;
        if (selectedSource === 'Structured') {
          const datasetId = dataSource?.datasetId ?? dataSource?.configdetails?.datasetId;
          if (!datasetId) {
            throw new Error('Structured data source requires datasetId');
          }
          console.warn('[QnaWidget] Creating structured session with datasetId:', datasetId);
          session = await createStructuredSession(apiBaseUrl, token, datasetId, innerConfig.allowModels?.[0]);
        } else {
          console.warn('[QnaWidget] Creating unstructured RAG session');
          session = await createRagSession(apiBaseUrl, token, innerConfig.allowModels?.[0]);
        }
        
        if (!isMounted) return;
        const sessionIdValue = (session?.sessionId || session?.session_id) as string;
        setSessionId(sessionIdValue);
      } catch (err) {
        if (!isMounted) return;
        const message = err instanceof Error ? err.message : 'Failed to initialize widget';
        setError(message);
        onError?.(message);
      } finally {
        if (isMounted) setLoading(false);
      }
    };

    if (token && widgetId) init();

    return () => {
      isMounted = false;
    };
  }, [token, widgetId, apiBaseUrl, onError]);

  // Extract sources and references from streaming response
  const extractSourcesAndReferences = (text: string) => {
    let rawText = text || '';
    if (typeof rawText === 'string') {
      rawText = rawText.replace(/^"|"$/g, '').trim();
    }

    let bBoxSplitIndex = rawText?.indexOf('\n\nb_box');
    if (bBoxSplitIndex === -1) {
      bBoxSplitIndex = rawText?.indexOf('b_box');
    }

    if (bBoxSplitIndex !== -1 && bBoxSplitIndex !== undefined) {
      let mainText = rawText?.substring(0, bBoxSplitIndex).trim();
      let bboxData = rawText?.slice(bBoxSplitIndex);

      mainText = mainText.replace(/\\n/g, '\n');
      bboxData = bboxData.replace(/^\s*b_box\s*/, '').trim();

      try {
        const refs = JSON.parse(bboxData);
        return {
          text: mainText,
          references: Array.isArray(refs)
            ? refs.map((ref: any, index: number) => ({
                id: index + 1,
                source: ref.metadata?.filename || 'Document',
                page: index + 1,
                content: ref.metadata?.text || `Reference ${index + 1}`,
                coords: ref,
                similarity_score: ref.similarity_score,
                chunk_id: ref.chunk_id,
              }))
            : [],
        };
      } catch {
        return { text: mainText, references: [] };
      }
    }

    const cleanText = rawText.replace(/\\n/g, '\n');
    return { text: cleanText || 'No answer available.', references: [] };
  };

  // Process all questions
  const handleGenerateAnswers = useCallback(async () => {
    if (!sessionId || questions.length === 0) return;

    setIsProcessing(true);
    setAnswers({});

    try {
      // For structured data, don't filter by file IDs
      if (dataSourceType === 'Structured') {
        for (const question of questions) {
          setCurrentlyProcessing(question);
          try {
                 const source = widget?.dataSources?.[0] as any;
                const namespace = source?.configdetails?.namespace ?? source?.namespace;
            const apiResponse = await queryStructuredQnA(
              apiBaseUrl,
              token,
              sessionId,
              question,
              widget?.apiprompt
            );
            const { text, references } = extractSourcesAndReferences(apiResponse);
            setAnswers((prev) => ({
              ...prev,
              [question]: { text, references },
            }));
          } catch (err) {
            console.error('Error processing question:', question, err);
            setAnswers((prev) => ({
              ...prev,
              [question]: { text: 'Error retrieving answer.', references: [] },
            }));
          }
        }
      } else {
        // Unstructured data: use file selection
        const documentIds = selectedFileIds.length > 0 ? selectedFileIds : availableFiles.map((f) => f.file_id || f.document_id);

        const hasMultipleFiles = selectedFileIds.length > 1 && availableFiles.length > 1;

        for (const question of questions) {
          setCurrentlyProcessing(question);
          try {
            if (hasMultipleFiles) {
              const fileAnswers: FileAnswer[] = [];

              for (const fileId of selectedFileIds) {
                const file = availableFiles.find((f: any) => (f.file_id || f.document_id) === fileId);
                const fileName = file ? file.originalName || file.fileName : fileId;
                const source = widget?.dataSources?.[0] as any;
                const namespace = source?.configdetails?.namespace ?? source?.namespace ?? resolvedNamespace;

                if (!namespace) {
                  fileAnswers.push({ fileId, fileName, text: 'No namespace configured for this Q&A source.', references: [] });
                  continue;
                }

                try {
                  const apiResponse = await queryQnA(
                    apiBaseUrl,
                    token,
                    sessionId,
                    question,
                    [fileId],
                    namespace,
                    widget?.topK,
                    widget?.apiprompt
                  );
                  const { text, references } = extractSourcesAndReferences(apiResponse);
                  fileAnswers.push({ fileId, fileName, text, references });

                  setAnswers((prev) => ({
                    ...prev,
                    [question]: { text: '', references: [], fileAnswers: [...fileAnswers] },
                  }));
                } catch (err) {
                  console.error('Error processing file:', fileId, err);
                  fileAnswers.push({ fileId, fileName, text: 'Error retrieving answer.', references: [] });
                }
              }
            } else {
              const source = widget?.dataSources?.[0] as any;
              const namespace = source?.configdetails?.namespace ?? source?.namespace ?? resolvedNamespace;
              if (!namespace) {
                setAnswers((prev) => ({
                  ...prev,
                  [question]: { text: 'No namespace configured for this Q&A source.', references: [] },
                }));
                continue;
              }
              const apiResponse = await queryQnA(
                apiBaseUrl,
                token,
                sessionId,
                question,
                documentIds,
                namespace,
                widget?.topK,
                widget?.apiprompt
              );
              const { text, references } = extractSourcesAndReferences(apiResponse);
              setAnswers((prev) => ({
                ...prev,
                [question]: { text, references },
              }));
            }
          } catch (err) {
            console.error('Error processing question:', question, err);
            setAnswers((prev) => ({
              ...prev,
              [question]: { text: 'Error retrieving answer.', references: [] },
            }));
          }
        }
      }
    } finally {
      setCurrentlyProcessing(null);
      setIsProcessing(false);
    }
  }, [sessionId, questions, selectedFileIds, availableFiles, token, apiBaseUrl, selectedModel, widget, dataSourceType, resolvedNamespace]);

  const isFloating = position === 'bottom-right';

  const content = loading ? (
    <div className="yw-qna-widget yw-qna-widget--loading">
      <div className="yw-qna-spinner" />
    </div>
  ) : error ? (
    <div className="yw-qna-widget yw-qna-widget--error">
      <p className="yw-qna-error-message">{error}</p>
    </div>
  ) : (
    <div className="yw-qna-widget">
      <div className="yw-qna-header">
        <h2 className="yw-qna-title">{widget?.widget_title || 'Q&A'}</h2>
        {dataSourceType === 'UnStructured' && (
          <div className="yw-qna-file-section">
            <FileSelectorDropdown
              files={availableFiles}
              selectedIds={selectedFileIds}
              onChange={setSelectedFileIds}
              isLoading={isLoadingFiles}
              emptyLabel="No files found"
              showNoSelectionNote={false}
            />
          </div>
        )}
      </div>

      {questions.length > 0 && (
        <div className="yw-qna-qa-section">
          {questions.map((question, qIdx) => (
            <div key={qIdx} className="yw-qna-question-block">
              <div className="yw-qna-question-title">Q{qIdx + 1}: {question}</div>

              {currentlyProcessing === question && !answers[question] ? (
                <div className="yw-qna-loading-state">
                  <div className="yw-qna-spinner-mini" />
                  <span>Generating answer...</span>
                </div>
              ) : answers[question] ? (
                <div className="yw-qna-answer-block">
                  {answers[question].fileAnswers && answers[question].fileAnswers!.length > 0 ? (
                    <div className="yw-qna-file-answers">
                      {answers[question].fileAnswers!.map((fa: FileAnswer) => (
                        <div key={fa.fileId} className="yw-qna-file-answer">
                          <div className="yw-qna-file-answer-name">📄 {fa.fileName}</div>
                          <div className="yw-qna-answer-text">{fa.text}</div>
                          {fa.references && fa.references.length > 0 && (
                            <div className="yw-qna-references">
                              <button
                                className="yw-qna-references-toggle"
                                onClick={() => {
                                  const key = `${qIdx}-file-${fa.fileId}`;
                                  setExpandedRefs((prev) => ({ ...prev, [key]: !prev[key] }));
                                }}
                              >
                                {expandedRefs[`${qIdx}-file-${fa.fileId}`] ? 'Hide' : 'Show'} References ({Math.min(8, fa.references.length)})
                              </button>
                              {expandedRefs[`${qIdx}-file-${fa.fileId}`] && (
                                <div className="yw-qna-reference-list">
                                  {fa.references.slice(0, 8).map((ref: Reference, rIdx: number) => (
                                    <ReferenceItem
                                      key={`${qIdx}-file-${fa.fileId}-ref-${rIdx}`}
                                      reference={ref}
                                      index={rIdx}
                                      isExpanded={expandedRefs[`${qIdx}-file-${fa.fileId}-ref-${rIdx}`]}
                                      onToggle={() => {
                                        const key = `${qIdx}-file-${fa.fileId}-ref-${rIdx}`;
                                        setExpandedRefs((prev) => ({ ...prev, [key]: !prev[key] }));
                                      }}
                                    />
                                  ))}
                                </div>
                              )}
                            </div>
                          )}
                        </div>
                      ))}
                    </div>
                  ) : (
                    <>
                      <div className="yw-qna-answer-text">{answers[question].text}</div>
                      {answers[question].references && answers[question].references!.length > 0 && (
                        <div className="yw-qna-references">
                          <button
                            className="yw-qna-references-toggle"
                            onClick={() => {
                              const key = `${qIdx}`;
                              setExpandedRefs((prev) => ({ ...prev, [key]: !prev[key] }));
                            }}
                          >
                            {expandedRefs[`${qIdx}`] ? 'Hide' : 'Show'} References ({Math.min(8, answers[question].references!.length)})
                          </button>
                          {expandedRefs[`${qIdx}`] && (
                            <div className="yw-qna-reference-list">
                              {answers[question].references!.slice(0, 8).map((ref: Reference, rIdx: number) => (
                                <ReferenceItem
                                  key={`${qIdx}-ref-${rIdx}`}
                                  reference={ref}
                                  index={rIdx}
                                  isExpanded={expandedRefs[`${qIdx}-ref-${rIdx}`]}
                                  onToggle={() => {
                                    const key = `${qIdx}-ref-${rIdx}`;
                                    setExpandedRefs((prev) => ({ ...prev, [key]: !prev[key] }));
                                  }}
                                />
                              ))}
                            </div>
                          )}
                        </div>
                      )}
                    </>
                  )}
                </div>
              ) : isProcessing ? (
                <div className="yw-qna-waiting-state">Waiting to process...</div>
              ) : null}
            </div>
          ))}
        </div>
      )}

      {questions.length > 0 && (
        <div className="yw-qna-controls">
          {widget?.allowModels && Array.isArray(widget.allowModels) && (
            <select value={selectedModel} onChange={(e) => setSelectedModel(e.target.value)} className="yw-qna-model-select">
              {widget.allowModels.map((model: string) => (
                <option key={model.trim()} value={model.trim()}>
                  {model.trim()}
                </option>
              ))}
            </select>
          )}
          <button onClick={handleGenerateAnswers} disabled={isProcessing || !sessionId} className="yw-qna-generate-button">
            {isProcessing ? `Generating... (${Object.keys(answers).length}/${questions.length})` : !sessionId ? 'Initializing...' : 'Generate Answers'}
          </button>
        </div>
      )}

      {!sessionId && !loading && questions.length > 0 && (
        <div className="yw-qna-initializing">
          <div className="yw-qna-spinner-mini" />
          <span>Initializing session...</span>
        </div>
      )}
    </div>
  );

  if (!isFloating) {
    return <div className={className || ''}>{content}</div>;
  }

  const panelStyle: any = {};
  if (floatingWidth) panelStyle.width = typeof floatingWidth === 'number' ? `${floatingWidth}px` : floatingWidth;
  if (floatingHeight) panelStyle.height = typeof floatingHeight === 'number' ? `${floatingHeight}px` : floatingHeight;

  return (
    <div className={`yw-floating-shell ${className || ''}`}>
      {!isOpen && (
        <button
          type="button"
          className="yw-floating-launcher"
          onClick={() => setIsOpen(true)}
          aria-label="Open QnA widget"
          title="Open QnA widget"
        >
          {launcherLabel}
        </button>
      )}

      {isOpen && (
        <div className="yw-floating-panel" style={panelStyle}>
          <div className="yw-floating-header">
            <strong className="yw-floating-title">{widget?.widget_title ?? 'Q&A'}</strong>
            <button
              type="button"
              className="yw-floating-close"
              onClick={() => setIsOpen(false)}
              aria-label="Close QnA widget"
            >
              x
            </button>
          </div>
          <div className="yw-floating-body">{content}</div>
        </div>
      )}
    </div>
  );
}
