'use client';

import React, { useCallback, useEffect, useMemo, useRef, useState } from 'react';
import type { LinkedInPostData, LinkedInPostGeneratorWidgetProps, NamespaceFile, WidgetDocument } from './types';
import {
  createRagSession,
  createStructuredSession,
  fetchNamespaces,
  fetchWidgetConfig,
  generateLinkedInPostFromDocuments,
  generateLinkedInPostFromStructuredData,
  resolveDocumentIds,
} from './api';
import { FileSelectorDropdown } from '../shared/FileSelectorDropdown';
import { renderMarkdown } from '../../lib/markdown';
import './linkedinpost.css';

const LinkedInIcon = () => (
  <svg viewBox="0 0 24 24" fill="currentColor" aria-hidden="true">
    <path d="M20.447 20.452h-3.554v-5.569c0-1.328-.027-3.037-1.852-3.037-1.853 0-2.136 1.445-2.136 2.939v5.667H9.351V9h3.414v1.561h.046c.477-.9 1.637-1.85 3.37-1.85 3.601 0 4.267 2.37 4.267 5.455v6.286zM5.337 7.433c-1.144 0-2.063-.926-2.063-2.065 0-1.138.92-2.063 2.063-2.063 1.14 0 2.064.925 2.064 2.063 0 1.139-.925 2.065-2.064 2.065zm1.782 13.019H3.555V9h3.564v11.452zM22.225 0H1.771C.792 0 0 .774 0 1.729v20.542C0 23.227.792 24 1.771 24h20.451C23.2 24 24 23.227 24 22.271V1.729C24 .774 23.2 0 22.222 0h.003z" />
  </svg>
);

function toDisplayName(file: NamespaceFile): string {
  return file.originalName ?? file.original_file_name ?? file.fileName ?? file.filename ?? file.file_id;
}

function stripMarkdown(md: string): string {
  return md
    .replace(/^#{1,6}\s+(.+)$/gm, '$1')
    .replace(/\*\*(.+?)\*\*/g, '$1')
    .replace(/__(.+?)__/g, '$1')
    .replace(/(?<!\*)\*(?!\*)(.+?)(?<!\*)\*(?!\*)/g, '$1')
    .replace(/(?<!_)_(?!_)(.+?)(?<!_)_(?!_)/g, '$1')
    .replace(/~~(.+?)~~/g, '$1')
    .replace(/^[\-*+]\s+/gm, '• ')
    .replace(/\[([^\]]+)\]\(([^\)]+)\)/g, '$1 ($2)')
    .replace(/```[\s\S]*?```/g, (m) => m.replace(/```\w*\n?/g, '').trim())
    .replace(/`([^`]+)`/g, '$1')
    .replace(/^>\s+/gm, '')
    .replace(/<[^>]*>/g, '')
    .replace(/\n{3,}/g, '\n\n')
    .trim();
}

function maxChars(lengthTarget?: string): number {
  if (lengthTarget === 'short') return 700;
  if (lengthTarget === 'long') return 3000;
  return 1500;
}

export function LinkedInPostGeneratorWidget({
  widgetId,
  token,
  apiBaseUrl,
  onTokenExpired,
  onError,
  className,
  position = 'inline',
  launcherLabel = 'in',
  floatingWidth,
  floatingHeight,
}: LinkedInPostGeneratorWidgetProps) {
  const base = apiBaseUrl.replace(/\/$/, '');
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [widget, setWidget] = useState<WidgetDocument | null>(null);
  const [sessionId, setSessionId] = useState<string | null>(null);
  const [availableFiles, setAvailableFiles] = useState<NamespaceFile[]>([]);
  const [selectedFileIds, setSelectedFileIds] = useState<string[]>([]);
  const [post, setPost] = useState<LinkedInPostData | null>(null);
  const [fetchingFresh, setFetchingFresh] = useState(false);
  const [isEditing, setIsEditing] = useState(false);
  const [editedContent, setEditedContent] = useState('');
  const [isCopied, setIsCopied] = useState(false);
  const [isOpen, setIsOpen] = useState(position !== 'bottom-right');

  const postRef = useRef<HTMLDivElement>(null);
  const hasAutoFetched = useRef(false);

  useEffect(() => {
    setIsOpen(position !== 'bottom-right');
  }, [position]);

  const config = widget?.config ?? {};
  const postContent = isEditing ? editedContent : post?.postContent ?? config.samplePost ?? 'Your AI-generated LinkedIn post will appear here.';
  const charLimit = maxChars(config.lengthTarget);
  const charCount = postContent.length;

  const selectedModel = useMemo(() => {
    const models = config.allowModels;
    if (Array.isArray(models) && models.length > 0) return models[0];
    if (typeof models === 'string' && models.trim()) return models;
    return 'gpt-4o-mini';
  }, [config.allowModels]);

  useEffect(() => {
    let disposed = false;

    const init = async () => {
      try {
        setLoading(true);
        setError(null);

        const doc = await fetchWidgetConfig(base, widgetId, token);
        if (disposed) return;
        setWidget(doc);

        const source = doc.config?.dataSources?.[0];
        const namespace = source?.configdetails?.namespace;
        const workspaceId = doc.config?.workspaceId;

        if (namespace && workspaceId) {
          const ns = await fetchNamespaces(base, workspaceId, token);
          if (disposed) return;
          const found = ns.find((n) => n.namespace === namespace);
          const files = found?.source ?? [];
          setAvailableFiles(files);

          const saved = doc.config?.selectedFileIds ?? [];
          if (saved.length > 0) {
            setSelectedFileIds(saved);
          } else {
            setSelectedFileIds(files.map((f) => f.file_id || f.document_id).filter(Boolean) as string[]);
          }
        }

        let sid: string | null = null;
        if (source?.selectedSource === 'Structured' || source?.configdetails?.datasetId || source?.datasetId) {
          const datasetId = source?.configdetails?.datasetId ?? source?.datasetId ?? '';
          if (datasetId) {
            const session = await createStructuredSession(base, token, datasetId, selectedModel);
            sid = session.sessionId ?? session.session_id ?? null;
          }
        } else if (source?.selectedSource === 'UnStructured' || !source?.selectedSource) {
          const session = await createRagSession(base, token, selectedModel);
          sid = session.session_id ?? null;
        }

        if (disposed) return;
        setSessionId(sid);
      } catch (err: any) {
        const message = err?.message ?? 'Failed to initialize LinkedIn widget';
        if (!disposed) {
          setError(message);
          onError?.(message);
        }
      } finally {
        if (!disposed) setLoading(false);
      }
    };

    init();
    return () => {
      disposed = true;
    };
  }, [base, widgetId, token, selectedModel, onError]);

  const generatePost = useCallback(async () => {
    if (!widget) return;
    try {
      setFetchingFresh(true);
      const source = widget.config?.dataSources?.[0];
      let text = '';

      if (source?.selectedSource === 'Structured') {
        if (!sessionId) throw new Error('Session not ready for structured generation');
        text = await generateLinkedInPostFromStructuredData(base, token, sessionId, widget.config);
      } else {
        const docIds = resolveDocumentIds(selectedFileIds, availableFiles);
        if (!docIds.length) throw new Error('No valid document found for post generation.');
        text = await generateLinkedInPostFromDocuments(base, token, docIds, widget.config, selectedModel);
      }

      const hashtags = text.match(/#[\w]+/g) || [];
      const sourceName = availableFiles.length > 0 ? toDisplayName(availableFiles[0]) : undefined;

      const nextPost: LinkedInPostData = {
        postContent: text,
        postType: widget.config?.postType || 'standard',
        lengthTarget: widget.config?.lengthTarget || 'medium',
        tone: widget.config?.tone || 'professional',
        characterCount: text.length,
        hashtags,
        source: {
          filename: sourceName,
          timestamp: new Date().toISOString(),
        },
      };
 
      setPost(nextPost);
      setEditedContent(text);
      setIsEditing(false);
    } catch (err: any) {
      const msg = err?.message ?? 'Could not generate LinkedIn post';
      if (msg.includes('401')) onTokenExpired?.();
      onError?.(msg);
      setError(msg);
    } finally {
      setFetchingFresh(false);
    }
  }, [widget, sessionId, base, token, selectedFileIds, availableFiles, selectedModel, onError, onTokenExpired]);

  useEffect(() => {
    if (loading || hasAutoFetched.current || !widget) return;
    const source = widget.config?.dataSources?.[0];
    if (source?.selectedSource === 'Structured' && !sessionId) return;
    hasAutoFetched.current = true;
    void generatePost();
  }, [loading, widget, sessionId, generatePost]);

  const copyPost = async () => {
    try {
      const text = stripMarkdown(postContent);
      await navigator.clipboard.writeText(text);
      setIsCopied(true);
      setTimeout(() => setIsCopied(false), 1600);
    } catch {
      onError?.('Failed to copy to clipboard');
    }
  };

  const downloadPost = () => {
    const text = stripMarkdown(postContent);
    const a = document.createElement('a');
    a.href = URL.createObjectURL(new Blob([text], { type: 'text/plain' }));
    a.download = `linkedin-post-${Date.now()}.txt`;
    document.body.appendChild(a);
    a.click();
    document.body.removeChild(a);
  };

  const shareToLinkedIn = async () => {
    const text = stripMarkdown(postContent);
    const shareUrl = `https://www.linkedin.com/sharing/share-offsite/?url=${encodeURIComponent(window.location.href)}&text=${encodeURIComponent(text)}`;
    window.open(shareUrl, '_blank', 'noopener,noreferrer');
    try {
      await navigator.clipboard.writeText(text);
    } catch {
      // no-op
    }
  };

  const saveEdit = () => {
    const next = editedContent.trim() ? editedContent : postContent;
    setPost((prev) => ({
      postContent: next,
      postType: prev?.postType ?? 'standard',
      lengthTarget: prev?.lengthTarget ?? 'medium',
      tone: prev?.tone ?? 'professional',
      characterCount: next.length,
      hashtags: next.match(/#[\w]+/g) || [],
      source: prev?.source,
    }));
    setIsEditing(false);
  };

  const content = loading ? (
    <div className="ylg-loading-wrap"><div className="ylg-spinner" /></div>
  ) : error ? (
    <div className="ylg-error-wrap">{error}</div>
  ) : (
    <div className="ylg-root">
      <div className="ylg-page-bg">
        <div className="ylg-container">
          {(config.widget_title || availableFiles.length > 0) && (
            <div className="ylg-top-row">
              <h1 className="ylg-title">{config.widget_title ?? 'LinkedIn Post Generator'}</h1>
              {availableFiles.length > 0 && (
                <div className="ylg-file-dd">
                  <FileSelectorDropdown
                    files={availableFiles}
                    selectedIds={selectedFileIds}
                    onChange={setSelectedFileIds}
                    showNoSelectionNote
                  />
                </div>
              )}
            </div>
          )}

          <div className={`ylg-card ylg-card--${config.cardStyle ?? 'elevated'}`}>
            <div className="ylg-header">
              <div className="ylg-header-left">
                <div className="ylg-badge"><LinkedInIcon /></div>
                <div>
                  <h3>LinkedIn Post Generator</h3>
                  <p>AI-Powered Content</p>
                </div>
              </div>
              <div className="ylg-icon-actions">
                <button onClick={copyPost} title={isCopied ? 'Copied' : 'Copy'}>{isCopied ? 'Copied' : 'Copy'}</button>
                <button onClick={downloadPost} title="Download">Download</button>
              </div>
            </div>

            <div className="ylg-meta">
              <div className="ylg-meta-left">
                <span>📝 {post?.postType ?? config.postType ?? 'standard'}</span>
                <span>✍️ {post?.tone ?? config.tone ?? 'professional'}</span>
                <span className={charCount > charLimit ? 'ylg-danger' : charCount > charLimit * 0.85 ? 'ylg-warn' : 'ylg-safe'}>
                  {charCount} / {charLimit} chars
                </span>
              </div>
              {!!post?.hashtags?.length && <span className="ylg-hash-count">#{post.hashtags.length} hashtags</span>}
            </div>

            <div className="ylg-content-box">
              {isEditing ? (
                <textarea
                  value={editedContent}
                  onChange={(e) => setEditedContent(e.target.value)}
                  className="ylg-editor"
                />
              ) : (
                <div ref={postRef} className="ylg-content ylg-markdown">{renderMarkdown(postContent)}</div>
              )}
            </div>

            {post?.source?.filename && (
              <div className="ylg-source">
                <span className="ylg-source-label">📄 Source:</span>
                <span>{post.source.filename}</span>
                {post.source.timestamp && <span className="ylg-source-time">{new Date(post.source.timestamp).toLocaleString()}</span>}
              </div>
            )}

            <div className="ylg-actions">
              <div className="ylg-actions-left">
                <button className="ylg-btn ylg-btn-muted" onClick={() => {
                  if (isEditing) {
                    setEditedContent(post?.postContent ?? '');
                    setIsEditing(false);
                  } else {
                    setEditedContent(post?.postContent ?? postContent);
                    setIsEditing(true);
                  }
                }}>
                  {isEditing ? 'Cancel' : 'Edit'}
                </button>
                {isEditing && (
                  <button className="ylg-btn ylg-btn-save" onClick={saveEdit}>Save</button>
                )}
              </div>
              <div className="ylg-actions-right">
                <button className="ylg-btn ylg-btn-linkedin" onClick={shareToLinkedIn}>Share to LinkedIn</button>
                <button className="ylg-btn ylg-btn-regen" onClick={() => void generatePost()} disabled={fetchingFresh}>
                  {fetchingFresh ? 'Generating...' : 'Regenerate'}
                </button>
              </div>
            </div>
          </div>

          {fetchingFresh && (
            <div className="ylg-floating-loader">
              <div className="ylg-spinner ylg-spinner--small" />
              <span>Generating LinkedIn post...</span>
            </div>
          )}
        </div>
      </div>
    </div>
  );

  if (position !== 'bottom-right') {
    return <div className={className ?? ''}>{content}</div>;
  }

  const panelStyle: React.CSSProperties = {};
  if (floatingWidth) panelStyle.width = typeof floatingWidth === 'number' ? `${floatingWidth}px` : floatingWidth;
  if (floatingHeight) panelStyle.height = typeof floatingHeight === 'number' ? `${floatingHeight}px` : floatingHeight;

  return (
    <div className={`ylg-floating-shell ${className ?? ''}`}>
      {!isOpen && (
        <button
          type="button"
          className="ylg-floating-launcher"
          onClick={() => setIsOpen(true)}
          aria-label="Open LinkedIn post widget"
          title="Open LinkedIn post widget"
        >
          {launcherLabel}
        </button>
      )}

      {isOpen && (
        <div className="ylg-floating-panel" style={panelStyle}>
          <div className="ylg-floating-header">
            <strong className="ylg-floating-title">{config.widget_title ?? 'LinkedIn Post Generator'}</strong>
            <button
              type="button"
              className="ylg-floating-close"
              onClick={() => setIsOpen(false)}
              aria-label="Close LinkedIn post widget"
            >
              x
            </button>
          </div>
          <div className="ylg-floating-body">{content}</div>
        </div>
      )}
    </div>
  );
}

export default LinkedInPostGeneratorWidget;
