import React, { useEffect, useRef, useState } from 'react';
import './file-selector-dropdown.css';

export interface SelectableFile {
  file_id?: string;
  document_id?: string;
  originalName?: string;
  fileName?: string;
  pages?: number;
  fileSize?: number;
}

interface FileSelectorDropdownProps {
  files: SelectableFile[];
  selectedIds: string[];
  onChange: (ids: string[]) => void;
  isLoading?: boolean;
  loadingLabel?: string;
  emptyLabel?: string;
  mode?: 'combine' | 'separate';
  onModeChange?: (mode: 'combine' | 'separate') => void;
  showNoSelectionNote?: boolean;
}

const ChevronDownIcon = ({ open }: { open: boolean }) => (
  <svg
    width="16"
    height="16"
    viewBox="0 0 24 24"
    fill="none"
    stroke="currentColor"
    strokeWidth="2"
    strokeLinecap="round"
    strokeLinejoin="round"
    style={{ transform: open ? 'rotate(180deg)' : 'none', transition: 'transform 0.2s' }}
  >
    <polyline points="6 9 12 15 18 9" />
  </svg>
);

function getFileId(file: SelectableFile): string | null {
  return file.file_id ?? file.document_id ?? null;
}

export function FileSelectorDropdown({
  files,
  selectedIds,
  onChange,
  isLoading = false,
  loadingLabel = 'Loading files...',
  emptyLabel = 'No files found',
  mode,
  onModeChange,
  showNoSelectionNote = true,
}: FileSelectorDropdownProps) {
  const [open, setOpen] = useState(false);
  const ref = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const handler = (e: MouseEvent) => {
      if (ref.current && !ref.current.contains(e.target as Node)) setOpen(false);
    };
    document.addEventListener('mousedown', handler);
    return () => document.removeEventListener('mousedown', handler);
  }, []);

  const fileIds = files.map(getFileId).filter((id): id is string => Boolean(id));

  const toggleFile = (id: string) => {
    onChange(selectedIds.includes(id) ? selectedIds.filter((x) => x !== id) : [...selectedIds, id]);
  };

  const toggleAll = () => {
    const allSelected = fileIds.length > 0 && fileIds.every((id) => selectedIds.includes(id));
    onChange(allSelected ? [] : fileIds);
  };

  const allSelected = fileIds.length > 0 && fileIds.every((id) => selectedIds.includes(id));
  const canOpen = !isLoading && files.length > 0;
  const shouldShowMode =
    Boolean(mode && onModeChange) &&
    (allSelected || selectedIds.length > 1) &&
    files.length > 1;

  const label = isLoading
    ? loadingLabel
    : files.length === 0
    ? emptyLabel
    : selectedIds.length === 0
    ? 'All files'
    : `${selectedIds.length} file${selectedIds.length !== 1 ? 's' : ''} selected`;

  return (
    <div className="yw-dropdown" ref={ref}>
      <button
        className="yw-dropdown-trigger"
        onClick={() => canOpen && setOpen(!open)}
        disabled={!canOpen}
      >
        <span>{label}</span>
        <ChevronDownIcon open={open} />
      </button>

      {open && (
        <div className="yw-dropdown-menu" onMouseDown={(e) => e.stopPropagation()}>
          <div className="yw-dropdown-item yw-dropdown-item--header" onClick={toggleAll}>
            <input
              type="checkbox"
              checked={allSelected}
              onChange={toggleAll}
              onClick={(e) => e.stopPropagation()}
              className="yw-checkbox"
            />
            <span className="yw-dropdown-selectall">Select All</span>
          </div>

          <div className={`yw-dropdown-list${files.length > 3 ? ' yw-dropdown-list--scroll' : ''}`}>
            {files.map((f, index) => {
              const fileId = getFileId(f);
              if (!fileId) return null;

              return (
                <div key={fileId || index} className="yw-dropdown-item" onClick={() => toggleFile(fileId)}>
                  <input
                    type="checkbox"
                    checked={selectedIds.includes(fileId)}
                    onChange={() => toggleFile(fileId)}
                    onClick={(e) => e.stopPropagation()}
                    className="yw-checkbox"
                  />
                  <div className="yw-dropdown-file">
                    <div className="yw-dropdown-filename">{f.originalName ?? f.fileName ?? fileId}</div>
                    {f.pages != null && (
                      <div className="yw-dropdown-filemeta">
                        {f.pages} page{f.pages !== 1 ? 's' : ''} • {((f.fileSize ?? 0) / 1024).toFixed(2)} KB
                      </div>
                    )}
                  </div>
                </div>
              );
            })}
          </div>

          {shouldShowMode && (
            <div className="yw-dropdown-footer">
              <div className="yw-dropdown-mode-label">Summary Mode</div>
              <div className="yw-dropdown-mode-options">
                <label className="yw-radio-label">
                  <input
                    type="radio"
                    value="combine"
                    checked={mode === 'combine'}
                    onChange={() => onModeChange?.('combine')}
                    className="yw-radio"
                  />
                  <span>Combine</span>
                </label>
                <label className="yw-radio-label">
                  <input
                    type="radio"
                    value="separate"
                    checked={mode === 'separate'}
                    onChange={() => onModeChange?.('separate')}
                    className="yw-radio"
                  />
                  <span>Separate</span>
                </label>
              </div>
            </div>
          )}

          {showNoSelectionNote && selectedIds.length === 0 && files.length > 0 && (
            <div className="yw-dropdown-note">
              <span className="yw-dropdown-note-bold">Note:</span> No files selected. All files will be used by default.
            </div>
          )}
        </div>
      )}
    </div>
  );
}
